# owner: platform
"""Lay students out in rows of seats."""

from rosterkit.errors import ProjectError


def _check(students, seats_per_row):
    if seats_per_row <= 0:
        raise ProjectError("seats per row must be positive")
    if not students:
        raise ProjectError("no students to seat")


def _sort_key(student):
    return (student.last_name, student.first_name)


def _chunks(items, size):
    return [
        items[start:start + size]
        for start in range(0, len(items), size)
    ]


def _format_row(number, group):
    names = " | ".join(item.display_name for item in group)
    return f"Row {number}: {names}"


# ---
def seat_rows(students, seats_per_row):
    """Return one line of text per row, by last name."""
    _check(students, seats_per_row)
    ordered = sorted(students, key=_sort_key)
    groups = _chunks(ordered, seats_per_row)
    return [
        _format_row(number, group)
        for number, group in enumerate(groups, start=1)
    ]

