# owner: platform
import unittest

from rosterkit.seating import seat_rows
from rosterkit.models import Student
from rosterkit.errors import ProjectError


def _make_student(last, first):
    return Student(last + first, last, first, "A")


class SeatRowsTests(unittest.TestCase):
    def setUp(self):
        self.students = [
            _make_student("Halloway", "Juno"),
            _make_student("Dunmere", "Piet"),
            _make_student("Zane", "Ola"),
        ]

    def test_rows_are_sorted_and_split(self):
        lines = seat_rows(self.students, 2)
        self.assertEqual(lines[1], "Row 2: Zane, Ola")
        expected = "Row 1: Dunmere, Piet | Halloway, Juno"
        self.assertEqual(lines[0], expected)

    def test_one_big_row(self):
        lines = seat_rows(self.students, 10)
        self.assertEqual(len(lines), 1)

    def test_same_last_name_uses_first_name(self):
        pair = [
            _make_student("Lee", "Zed"),
            _make_student("Lee", "Amy"),
        ]
        lines = seat_rows(pair, 2)
        expected = ["Row 1: Lee, Amy | Lee, Zed"]
        self.assertEqual(lines, expected)

    def test_zero_seats_raises(self):
        with self.assertRaises(ProjectError):
            seat_rows(self.students, 0)

    def test_negative_seats_raises(self):
        with self.assertRaises(ProjectError):
            seat_rows(self.students, -3)

    def test_no_students_raises(self):
        with self.assertRaises(ProjectError):
            seat_rows([], 2)
